const root = $json;
const headers = root.headers || {};
const receivedKey = String(headers['x-api-key'] || headers['X-API-Key'] || '');
const expectedKey = String($env.N8N_API_KEY || '');

if (!expectedKey || !receivedKey || receivedKey !== expectedKey) {
  throw new Error('Acesso não autorizado ao webhook do portal.');
}

const b = root.body ?? root;
const mode = ['conversation', 'diagnostic'].includes(String(b.mode || 'conversation'))
  ? String(b.mode || 'conversation')
  : 'conversation';

const message = String(b.message || '').trim();
if (!message) throw new Error('Mensagem obrigatória.');

return [{
  json: {
    student_id: String(b.student_id || ''),
    name: String(b.name || 'Aluno'),
    phone: String(b.phone || '').replace(/\D/g, ''),
    message,
    message_type: b.message_type === 'audio' ? 'audio' : 'text',
    is_audio: b.message_type === 'audio',
    channel: String(b.channel || 'web'),
    mode,
    topic: String(b.topic || (mode === 'diagnostic' ? 'initial_diagnostic' : 'daily_life')),
    correction_mode: String(b.correction_mode || 'balanced'),
    conversation: {
      style: String(b.conversation?.style || 'guided'),
      max_turns: Math.max(4, Math.min(30, Number(b.conversation?.max_turns || 10)))
    }
  }
}];

const j = $json;
const s = j.student || {};
const currentStep = Math.max(0, Number(s.diagnostic_step ?? j.diagnostic_step ?? 0) || 0);
const message = String(j.message || '').trim();
const normalized = message
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '')
  .toLowerCase()
  .trim();

function detectChoice(value) {
  const number = value.match(/(?:^|\b)([1-5])(?:\b|$)/);
  if (number) return Number(number[1]);
  if (value.includes('nunca') || value.includes('nao sei nada') || value.includes('zero')) return 1;
  if (value.includes('algumas palavras') || value.includes('reconheco palavras')) return 2;
  if (value.includes('frases simples') || value.includes('escrever frases')) return 3;
  if (value.includes('conversar um pouco') || value.includes('converso um pouco')) return 4;
  if (value.includes('descubra') || value.includes('durante a conversa')) return 5;
  return null;
}

const choices = {
  1: {
    level: 'PRE-A1', band: 'PRE-A1', support: 'pt_first', teaching: 'foundations', language: 'portuguese', explanation: 'pt-BR', correction: 'light',
    reply: `Perfeito. Vamos começar do início, com calma e sem pressão.\n\nEm inglês, “Olá” é *Hello*.\n\nQual opção significa “Hello”?\n\n1. Olá\n2. Obrigado\n3. Tchau`
  },
  2: {
    level: 'A1', band: 'A1 inicial', support: 'bilingual', teaching: 'guided', language: 'portuguese', explanation: 'pt-BR', correction: 'light',
    reply: `Ótimo. Vou usar inglês bem simples e explicar em português quando precisar.\n\nComplete a frase:\n\nMy name ___ Ana.\n\n1. is\n2. are\n3. am`
  },
  3: {
    level: 'A2', band: 'A1–A2', support: 'bilingual', teaching: 'guided_conversation', language: 'adaptive', explanation: 'pt-BR', correction: 'balanced',
    reply: `Ótimo. Vamos começar com inglês simples e apoio em português quando necessário.\n\nPlease answer in English:\n\nWhat is your name and where are you from?\n\nVocê pode usar: “My name is ____. I am from ____.”`
  },
  4: {
    level: 'B1', band: 'A2–B1', support: 'english_first', teaching: 'conversation', language: 'adaptive', explanation: 'adaptive', correction: 'balanced',
    reply: `Ótimo. Vamos conversar em inglês, mas você pode pedir explicação em português a qualquer momento.\n\nTell me about your daily routine. What do you usually do in the morning?\n\nPlease answer in two or three sentences.`
  },
  5: {
    level: 'A1', band: 'em descoberta', support: 'bilingual', teaching: 'guided_conversation', language: 'adaptive', explanation: 'adaptive', correction: 'balanced',
    reply: `Tudo bem. Vou começar com uma pergunta simples e adaptar as próximas de acordo com suas respostas.\n\nWhat is your name and what do you like to do in your free time?\n\nVocê pode responder em inglês ou português.`
  }
};

function diagnosticBase(overrides = {}) {
  return {
    reply: '', current_step: currentStep, next_step: Math.min(currentStep + 1, 5), complete: false,
    self_assessment_option: s.initial_self_assessment ?? null,
    provisional_band: '', estimated_level: s.estimated_level || s.overall_level || 'PRE-A1', confidence: Number(s.diagnostic_confidence || 0),
    language_support: s.preferred_language_support || 'portuguese',
    support_mode: s.support_mode || 'pt_first', teaching_mode: s.teaching_mode || 'foundations',
    preferred_explanation_language: s.preferred_explanation_language || 'pt-BR', correction_mode: s.correction_mode || 'balanced',
    translation_on_request: true, audio_sample_received: j.is_audio === true || j.message_type === 'audio',
    scores: {reception:0,interaction:0,production:0,grammar:0,vocabulary:0,fluency:0,coherence:0,pronunciation:null},
    cefr_evidence: [], strengths: [], weaknesses: [], recommendations: [], corrections: [], study_plan: {}, first_activity: {},
    ...overrides
  };
}

let direct = null;
if (currentStep === 0) {
  direct = diagnosticBase({
    reply: `Olá! Eu sou a Emma, sua professora de inglês. 😊\n\nAntes de começarmos, quero entender como posso ensinar você da melhor forma. Não se preocupe: você pode responder em português.\n\nQual opção mais combina com você hoje?\n\n1. Nunca estudei inglês ou não sei praticamente nada\n2. Reconheço algumas palavras, mas não consigo formar frases\n3. Consigo entender e escrever frases simples\n4. Consigo conversar um pouco, mesmo cometendo erros\n5. Prefiro que você descubra meu nível durante a conversa`,
    next_step: 1, self_assessment_option: null, provisional_band: 'acolhimento', estimated_level: 'PRE-A1', confidence: 0,
    support_mode: 'pt_first', teaching_mode: 'foundations', language_support: 'portuguese', preferred_explanation_language: 'pt-BR', correction_mode: 'light'
  });
} else if (currentStep === 1) {
  const choice = detectChoice(normalized);
  if (!choice) {
    direct = diagnosticBase({
      reply: `Para eu adaptar o início, responda somente com um número de 1 a 5.\n\n1. Nunca estudei ou não sei praticamente nada\n2. Reconheço palavras, mas não formo frases\n3. Entendo e escrevo frases simples\n4. Consigo conversar um pouco\n5. Prefiro que você descubra durante a conversa`,
      next_step: 1, self_assessment_option: null, confidence: 0
    });
  } else {
    const mode = choices[choice];
    direct = diagnosticBase({
      reply: mode.reply, next_step: 2, self_assessment_option: choice, provisional_band: mode.band,
      estimated_level: mode.level, confidence: 10, support_mode: mode.support, teaching_mode: mode.teaching,
      language_support: mode.language, preferred_explanation_language: mode.explanation, correction_mode: mode.correction
    });
  }
}

const supportMode = s.support_mode || direct?.support_mode || 'pt_first';
const teachingMode = s.teaching_mode || direct?.teaching_mode || 'foundations';
const history = Array.isArray(j.recent_messages) ? j.recent_messages : [];

const diagnosticPrompt = `Você é Emma, professora e avaliadora do RS English. Conduza um diagnóstico pedagógico adaptativo alinhado ao QECR/CEFR.

REGRAS INEGOCIÁVEIS
- A primeira abordagem é em português. Nunca presuma que o aluno entende inglês.
- Ensine enquanto avalia. Não transforme a experiência em uma prova hostil.
- Faça apenas uma pergunta ou tarefa por vez.
- A autoavaliação define somente a dificuldade inicial, nunca o nível final.
- Se houver bloqueio, explique em português e reduza a dificuldade.
- Se houver facilidade, aumente a dificuldade gradualmente.
- Não repita perguntas já respondidas.
- Não invente problemas de pronúncia sem áudio.
- A classificação é uma estimativa pedagógica, não uma certificação oficial.

DADOS
Nome: ${s.name || j.name || 'Aluno'}
Etapa: ${currentStep}
Autoavaliação: ${s.initial_self_assessment ?? 'não registrada'}
Faixa provisória: ${s.estimated_level || 'PRE-A1'}
Modo de apoio: ${supportMode}
Modo de ensino: ${teachingMode}
Mensagem atual: ${message}
Mensagem é áudio: ${j.is_audio === true || j.message_type === 'audio'}
Histórico recente: ${JSON.stringify(history)}

POLÍTICA DE IDIOMA
- pt_first: explique principalmente em português e introduza inglês em pequenas doses, sempre com modelo claro.
- bilingual: use inglês simples com apoio em português.
- english_first: use principalmente inglês e português para correção, tradução ou bloqueio.
- english_only: use inglês; volte ao português apenas se o aluno pedir ou demonstrar bloqueio real.

ETAPAS
2: avalie a primeira amostra e proponha uma tarefa pessoal adequada ao nível.
3: avalie produção/interação e peça uma tarefa envolvendo passado, sequência ou experiência, adaptada à faixa.
4: avalie coerência e independência. Peça opinião/plano. Se ainda não houve áudio, convide para áudio de 20–40 segundos, permitindo texto.
5: conclua com nível estimado, capacidades observadas, 2 pontos fortes, 2–3 prioridades, limitações, plano de 28 dias e primeira atividade.

Na etapa 5, complete=true. Nas etapas 2–4, complete=false e next_step deve avançar somente uma etapa.

Retorne SOMENTE JSON válido:
{
  "reply":"",
  "current_step":${currentStep},
  "next_step":${Math.min(currentStep + 1, 5)},
  "complete":${currentStep >= 5},
  "self_assessment_option":${s.initial_self_assessment ?? 'null'},
  "provisional_band":"",
  "estimated_level":"${s.estimated_level || 'PRE-A1'}",
  "confidence":0,
  "language_support":"${s.preferred_language_support || 'portuguese'}",
  "support_mode":"${supportMode}",
  "teaching_mode":"${teachingMode}",
  "preferred_explanation_language":"${s.preferred_explanation_language || 'pt-BR'}",
  "correction_mode":"${s.correction_mode || 'balanced'}",
  "translation_on_request":true,
  "audio_sample_received":${j.is_audio === true || j.message_type === 'audio'},
  "scores":{"reception":0,"interaction":0,"production":0,"grammar":0,"vocabulary":0,"fluency":0,"coherence":0,"pronunciation":null},
  "cefr_evidence":[],"strengths":[],"weaknesses":[],"recommendations":[],"corrections":[],"study_plan":{},"first_activity":{}
}`;

return [{json:{...j,current_step:currentStep,direct_response:Boolean(direct),direct_diagnostic:direct,diagnostic_prompt:diagnosticPrompt}}];

const source = $('Montar Prompt Diagnóstico Web').item.json;
const response = $json;
let text = response.output_text;
if (!text && Array.isArray(response.output)) {
  const parts=[];
  for (const item of response.output) for (const c of (item.content || [])) if (typeof c.text === 'string') parts.push(c.text);
  text=parts.join('\n');
}
text=String(text || '').replace(/^```json\s*/i,'').replace(/^```\s*/i,'').replace(/```$/,'').trim();
let diagnostic=null;
try { diagnostic=JSON.parse(text); } catch (_) {
  const match=text.match(/\{[\s\S]*\}/);
  if (match) try { diagnostic=JSON.parse(match[0]); } catch (_) {}
}
const step=Math.max(2,Number(source.current_step || 2));
const s=source.student || {};
function fallback() {
  const support=s.support_mode || 'pt_first';
  const pt=support==='pt_first' || support==='bilingual';
  if (step===2) return pt
    ? 'Muito bem. Agora me conte algo simples sobre sua rotina. Você pode escrever uma ou duas frases em inglês; eu ajudo se precisar.'
    : 'Good. Now tell me about your daily routine in one or two sentences.';
  if (step===3) return pt
    ? 'Agora fale sobre ontem ou sobre o último fim de semana. Escreva duas ou três frases; pode pedir um modelo.'
    : 'Tell me about something you did yesterday or last weekend in two or three sentences.';
  if (step===4) return pt
    ? 'Para completar esta etapa, conte um objetivo para os próximos meses e por que ele é importante. Pode responder por áudio ou texto.'
    : 'Tell me one goal you have for the next few months and why it is important. You may answer by audio or text.';
  return `Concluímos seu diagnóstico inicial.\n\nNível estimado pelo QECR: ${s.estimated_level || s.overall_level || 'A1'}.\n\nEsta é uma estimativa pedagógica e será refinada com novas interações.\n\nPontos fortes:\n• participação nas atividades\n• disposição para produzir inglês\n\nPrioridades:\n• ampliar vocabulário\n• organizar frases com mais segurança\n• praticar conversação regularmente\n\nPrimeira atividade: apresente-se e fale brevemente sobre sua rotina.`;
}
if (!diagnostic || typeof diagnostic !== 'object') diagnostic={reply:fallback()};
const levels=['PRE-A1','A1','A2','B1','B2','C1','C2'];
let level=String(diagnostic.estimated_level || s.estimated_level || s.overall_level || 'PRE-A1').toUpperCase();
if (!levels.includes(level)) level='PRE-A1';
const allowedSupport=['pt_first','bilingual','english_first','english_only'];
const allowedTeaching=['foundations','guided','guided_conversation','conversation','immersion'];
diagnostic.current_step=step;
diagnostic.next_step=step>=5?5:Math.min(step+1,5);
diagnostic.complete=step>=5;
diagnostic.estimated_level=level;
diagnostic.self_assessment_option=diagnostic.self_assessment_option ?? s.initial_self_assessment ?? null;
diagnostic.support_mode=allowedSupport.includes(diagnostic.support_mode)?diagnostic.support_mode:(s.support_mode || 'pt_first');
diagnostic.teaching_mode=allowedTeaching.includes(diagnostic.teaching_mode)?diagnostic.teaching_mode:(s.teaching_mode || 'foundations');
diagnostic.language_support=['portuguese','adaptive','english'].includes(diagnostic.language_support)?diagnostic.language_support:(s.preferred_language_support || 'portuguese');
diagnostic.preferred_explanation_language=['pt-BR','adaptive','en'].includes(diagnostic.preferred_explanation_language)?diagnostic.preferred_explanation_language:(s.preferred_explanation_language || 'pt-BR');
diagnostic.correction_mode=['light','balanced','intensive'].includes(diagnostic.correction_mode)?diagnostic.correction_mode:(s.correction_mode || 'balanced');
diagnostic.confidence=Math.max(0,Math.min(100,Number(diagnostic.confidence || 35)));
diagnostic.audio_sample_received=Boolean(diagnostic.audio_sample_received || source.is_audio || source.message_type==='audio');
for (const key of ['cefr_evidence','strengths','weaknesses','recommendations','corrections']) if (!Array.isArray(diagnostic[key])) diagnostic[key]=[];
for (const key of ['scores','study_plan','first_activity']) if (!diagnostic[key] || typeof diagnostic[key] !== 'object') diagnostic[key]={};
if (!String(diagnostic.reply || '').trim()) diagnostic.reply=fallback();
return [{json:{...source,diagnostic,teacher_message:String(diagnostic.reply).trim(),diagnostic_parse_ok:Boolean(text)}}];

const j=$json;
const s=j.student || {};
const prefs=j.student_preferences || {};
const level=s.overall_level || s.estimated_level || 'PRE-A1';
const support=s.support_mode || 'pt_first';
const teaching=s.teaching_mode || 'foundations';
const correction=prefs.correction_mode || s.correction_mode || 'balanced';
const message=String(j.message || '').trim();
const conversation=j.conversation || {topic:prefs.conversation_topic || 'daily_life',style:prefs.conversation_style || 'guided',turn_count:0,max_turns:Number(prefs.conversation_max_turns || 10)};
const policy={
  pt_first:'Fale principalmente em português. Introduza apenas uma pequena parte em inglês por vez, com significado e modelo. Nunca abandone o aluno em uma conversa só em inglês.',
  bilingual:'Use inglês simples e apoio em português. Traduza ou modele quando houver insegurança.',
  english_first:'Use principalmente inglês. Use português para correção, explicação ou quando o aluno demonstrar bloqueio.',
  english_only:'Use inglês como idioma principal. Volte ao português somente se o aluno pedir ou demonstrar bloqueio real.'
}[support] || 'Adapte o idioma à compreensão do aluno.';
const teachingPolicy={
  foundations:'Ensine do zero. Uma expressão ou estrutura por vez. Celebre progresso pequeno e use exemplos concretos.',
  guided:'Faça prática guiada com modelos curtos e alternativas quando necessário.',
  guided_conversation:'Conduza conversação simples, oferecendo modelo antes de exigir produção independente.',
  conversation:'Mantenha conversa natural, corrija sem interromper demais e aumente a complexidade gradualmente.',
  immersion:'Mantenha imersão, naturalidade e desafios compatíveis com o nível.'
}[teaching] || '';
const teacherPrompt=`Você é Emma, professora particular de inglês do RS English.
Aluno: ${s.name || j.name || 'Aluno'}
Nível estimado: ${level}
Modo de apoio: ${support}
Modo de ensino: ${teaching}
Modo de correção: ${correction}
Tema: ${conversation.topic || 'daily_life'}
Histórico: ${JSON.stringify(j.recent_messages || [])}
Mensagem atual: ${message}

POLÍTICA: ${policy}
METODOLOGIA: ${teachingPolicy}

Regras:
- acolha antes de corrigir;
- faça somente uma pergunta por resposta;
- não repita pergunta já respondida;
- se o aluno disser que não entendeu, reduza a dificuldade imediatamente;
- no modo foundations, ensine enquanto conversa;
- light: no máximo 1 correção essencial; balanced: 1 correção relevante; intensive: até 2;
- para áudio diga “você disse”; para texto diga “você escreveu”;
- não informe nível ou faça novo diagnóstico agora;
- responda somente com a mensagem que será enviada ao aluno.`;
const evaluatorPrompt=`Avalie a mensagem do aluno no contexto abaixo e retorne somente JSON válido.
Nível: ${level}. Apoio: ${support}. Ensino: ${teaching}. Correção: ${correction}.
Mensagem do aluno: ${message}
Resposta da professora será gerada separadamente.
Retorne: {"grammar_score":null,"vocabulary_score":null,"fluency_score":null,"comprehension_score":null,"corrections":[],"errors":[],"skills":[],"session_complete":false,"session_summary":"","summary_data":{}}.
Não invente pronúncia sem áudio. Limite correções conforme o modo.`;
return [{json:{...j,level,support_mode:support,teaching_mode:teaching,correction_mode:correction,conversation,teacher_prompt:teacherPrompt,evaluator_prompt:evaluatorPrompt}}];

const r = $json;

let text = r.output_text;

if (!text && Array.isArray(r.output)) {
  const parts = [];

  for (const item of r.output) {
    for (const content of item.content ?? []) {
      if (typeof content.text === 'string') {
        parts.push(content.text);
      }
    }
  }

  text = parts.join('\n');
}

text = String(text ?? '')
  .replace(/^```json\s*/i, '')
  .replace(/^```\s*/i, '')
  .replace(/```$/i, '')
  .trim();

let evaluation;

try {
  evaluation = JSON.parse(text);
} catch (error) {
  evaluation = {
    grammar_score: null,
    vocabulary_score: null,
    fluency_score: null,
    comprehension_score: null,
    corrections: [],
    errors: [],
    skills: []
  };
}

if (!Array.isArray(evaluation.corrections)) {
  evaluation.corrections = [];
}

if (!Array.isArray(evaluation.errors)) {
  evaluation.errors = [];
}

if (!Array.isArray(evaluation.skills)) {
  evaluation.skills = [];
}

return [{
  json: {
    evaluation
  }
}];
